def sha(dados: bytes) -> str:
    return hashlib.sha256(dados).hexdigest()


def localizar_raiz() -> Path:
    for raiz in (Path.cwd().resolve(), Path(__file__).resolve().parent):
        if (raiz / "backend/app/principal.py").is_file() and (raiz / "frontend/package.json").is_file():
            return raiz
    raise RuntimeError("Salve e execute este arquivo na raiz C:\\Users\\Omega\\Desktop\\MEC-Servicos.")


def seguro(raiz: Path, relativo: str) -> Path:
    alvo = raiz / relativo
    if alvo.is_symlink() or any(p.is_symlink() for p in alvo.parents if p != raiz and raiz in p.parents):
        raise RuntimeError("Destino simbólico preservado: " + relativo)
    if not alvo.resolve().is_relative_to(raiz): raise RuntimeError("Destino fora do projeto.")
    return alvo


def executar_git(raiz: Path, *args: str) -> str:
    git = shutil.which("git")
    if not git: raise RuntimeError("Git não encontrado.")
    r = subprocess.run([git, *args], cwd=raiz, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=30)
    if r.returncode: raise RuntimeError("Não foi possível conferir o projeto com Git.")
    return r.stdout.strip()


def origem_mec(url: str) -> bool:
    if url.startswith("git@github.com:"): caminho = url.split(":", 1)[1]
    else:
        p = urlsplit(url)
        if p.scheme not in {"https", "ssh"} or p.hostname != "github.com" or (p.scheme == "https" and (p.username or p.password)):
            return False
        caminho = p.path.lstrip("/")
    return caminho.lower().rstrip("/").removesuffix(".git") == "projetoxcadcam-byte/mec-servicos"


def fonte_confere(dados: bytes, esperado: str) -> bool:
    normal = dados.replace(b"\r\n", b"\n")
    return esperado in {sha(dados), sha(normal), sha(normal.replace(b"\n", b"\r\n"))}


def exigir_backend_parado() -> None:
    try:
        with socket.create_connection(("127.0.0.1", 8000), timeout=0.5):
            pass
    except OSError:
        return
    raise RuntimeError("A porta 8000 está em uso. Pare o backend com Ctrl+C no terminal dele antes de executar o D31 FIX2.")


def configuracao_bancos(raiz: Path):
    sys.path.insert(0, str(raiz))
    from backend.app.core.configuracao import configuracoes
    if configuracoes.prefixo_api.rstrip("/") != "/api/v1": raise RuntimeError("Confira o prefixo /api/v1.")
    url = configuracoes.url_banco_dados
    if not url.startswith("sqlite:///"): raise RuntimeError("Este FIX2 foi preparado para o banco SQLite local.")
    banco = Path(url[len("sqlite:///"):]); banco = (raiz / banco).resolve() if not banco.is_absolute() else banco.resolve()
    if not banco.is_file() or not banco.is_relative_to(raiz): raise RuntimeError("Banco de negócio local não encontrado.")
    acesso = Path(os.environ.get("MEC_ACESSOS_DB", str(raiz / "data/mec_acessos.db")))
    acesso = (raiz / acesso).resolve() if not acesso.is_absolute() else acesso.resolve()
    if not acesso.is_file() or not acesso.is_relative_to(raiz): raise RuntimeError("Banco de acesso D30 local não encontrado.")
    if acesso == banco: raise RuntimeError("O banco de acesso deve ser separado do banco de negócio.")
    with closing(sqlite3.connect(acesso.as_uri() + "?mode=ro", uri=True)) as c:
        c.execute("PRAGMA query_only=ON")
        if not c.execute("SELECT COUNT(*) FROM usuarios_acesso WHERE perfil='admin' AND ativo=1").fetchone()[0]:
            raise RuntimeError("Não foi encontrado administrador ativo no banco de acesso.")
    return banco, acesso


def identidade_sql(nome: str) -> str:
    return '"' + nome.replace('"', '""') + '"'


def historico(conexao, tabelas=None):
    if tabelas is None:
        tabelas = [n for (n,) in conexao.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")]
    resultado = {}
    for nome in tabelas:
        sql = conexao.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name=?", (nome,)).fetchone()
        if sql is None: raise RuntimeError("Tabela anterior desapareceu: " + nome)
        linhas = [json.dumps(list(l), ensure_ascii=False, default=lambda b: b.hex(), separators=(",", ":"))
                  for l in conexao.execute("SELECT * FROM " + identidade_sql(nome))]
        resultado[nome] = sha(json.dumps([sql[0], sorted(linhas)], ensure_ascii=False).encode("utf-8"))
    return resultado


def ler_historico(banco: Path, tabelas=None):
    with closing(sqlite3.connect(banco.as_uri() + "?mode=ro", uri=True)) as c:
        c.execute("PRAGMA query_only=ON"); c.execute("BEGIN")
        return historico(c, tabelas)


def conferir_schema(conexao):
    existem = {n for (n,) in conexao.execute("SELECT name FROM sqlite_master WHERE type='table'")}
    presentes = existem.intersection(TABELAS_D31)
    if presentes and presentes != set(TABELAS_D31): raise RuntimeError("Estrutura D31 parcial encontrada; banco preservado.")
    if not presentes: return False
    for nome, esperado in SCHEMA_D31.items():
        atual = [(l[1], l[2].upper(), bool(l[3]), bool(l[5])) for l in conexao.execute("PRAGMA table_info(" + identidade_sql(nome) + ")")]
        if atual != [tuple(l) for l in esperado]: raise RuntimeError("Estrutura D31 divergente; banco preservado: " + nome)
        sql = conexao.execute("SELECT sql FROM sqlite_master WHERE name=? AND type='table'", (nome,)).fetchone()[0]
        if "".join(sql.split()).lower() != "".join(DDL_TABELAS[nome].strip().split()).lower():
            raise RuntimeError("Restrições D31 divergentes; banco preservado: " + nome)
    return True


def executar(raiz, rotulo, comando, ambiente, relatorio):
    relatorio["etapa"] = rotulo
    print("Executando " + rotulo + "...", flush=True)
    r = subprocess.run(comando, cwd=raiz, env=ambiente, capture_output=True, text=True, encoding="utf-8", errors="replace")
    saida = r.stdout + r.stderr
    print(saida, end="" if saida.endswith("\n") else "\n", flush=True)
    relatorio[rotulo] = {"return_code": r.returncode, "saida": saida}
    print(rotulo.upper() + "_RETURN_CODE=" + str(r.returncode), flush=True)
    if r.returncode: raise RuntimeError("A etapa " + rotulo + " falhou; confira o relatório.")


def salvar_relatorio(raiz: Path, relatorio):
    conteudo = json.dumps(relatorio, ensure_ascii=False, indent=2) + "\n"
    for extensao in ("json", "txt"):
        alvo = seguro(raiz, STEM + "." + extensao)
        with tempfile.NamedTemporaryFile(mode="w", encoding="utf-8", newline="\n", dir=raiz, delete=False, prefix="mec_d31_relatorio_") as temp:
            temp.write(conteudo); caminho = Path(temp.name)
        try: os.replace(caminho, alvo)
        finally: caminho.unlink(missing_ok=True)
        print(("JSON=" if extensao == "json" else "RELATORIO=") + str(alvo), flush=True)


def plano_arquivos(raiz: Path) -> dict[str, bytes]:
    novos = {nome: fonte.encode("utf-8") for nome, fonte in FONTES.items()}
    for nome, esperado in BASE_SHA256.items():
        arquivo = seguro(raiz, nome)
        if not arquivo.is_file():
            raise RuntimeError("Fonte D31 esperado ausente: " + nome)
        atual = arquivo.read_bytes()
        if not fonte_confere(atual, esperado) and not (nome in novos and fonte_confere(atual, sha(novos[nome]))):
            raise RuntimeError("Fonte diferente da base D31 conhecida; preservado: " + nome)
    for nome, novo in novos.items():
        arquivo = seguro(raiz, nome)
        if arquivo.exists() and nome not in BASE_SHA256 and not fonte_confere(arquivo.read_bytes(), sha(novo)):
            raise RuntimeError("Arquivo já existe com outro conteúdo; preservado: " + nome)
        if nome.endswith(".py"):
            ast.parse(novo, filename=nome)
    return {n: b for n, b in novos.items() if not (raiz / n).is_file() or not fonte_confere((raiz / n).read_bytes(), sha(b))}


def gravar_atomico(alvo: Path, conteudo: bytes) -> None:
    alvo.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(dir=alvo.parent, delete=False, prefix="mec_fix2_") as temp:
        temp.write(conteudo)
        caminho = Path(temp.name)
    try:
        os.replace(caminho, alvo)
    finally:
        caminho.unlink(missing_ok=True)


def conferir_d31(raiz: Path, banco: Path, acesso: Path) -> list[dict]:
    anterior = seguro(raiz, "MEC_SERVICOS_V0_1_D31_INTERMEDIACAO_ADMIN_RELATORIO.json")
    if not anterior.is_file():
        raise RuntimeError("Relatório da instalação D31 não encontrado.")
    dados = json.loads(anterior.read_text(encoding="utf-8-sig"))
    if dados.get("resultado") != "OK" or dados.get("revision") != D31_REVISION:
        raise RuntimeError("A instalação D31 precisa estar concluída antes deste FIX2.")
    with closing(sqlite3.connect(banco.as_uri() + "?mode=ro", uri=True)) as c:
        if not conferir_schema(c):
            raise RuntimeError("Tabelas D31 ausentes; banco preservado.")
    with closing(sqlite3.connect(acesso.as_uri() + "?mode=ro", uri=True)) as c:
        c.row_factory = sqlite3.Row
        contas = [dict(r) for r in c.execute("SELECT id AS usuario_id,nome,email,perfil,empresa_id FROM usuarios_acesso WHERE ativo=1 ORDER BY id")]
    if not any(c["perfil"] == "fornecedor" and c["empresa_id"] == 1 for c in contas):
        raise RuntimeError("Conta ativa da oficina (empresa #1) não encontrada. Confira o resultado do D31 FIX1 de acesso.")
    return contas


def main() -> int:
    print("MEC-Serviços D31 FIX2 — Modo de teste local", flush=True)
    print("REVISION=" + REVISION, flush=True)
    raiz = None
    originais = {}
    alterados = []
    pastas_novas = []
    backup = None
    dist_existia = False
    build_iniciado = False
    concluido = False
    relatorio = {"revision": REVISION, "resultado": "ERRO", "etapa": "inicio", "restaurado": False,
        "modo_teste_ativado_na_instalacao": False, "senhas_redefinidas": False}
    try:
        if sys.version_info < (3, 11):
            raise RuntimeError("Use a .venv com Python 3.11 ou mais recente.")
        raiz = localizar_raiz()
        print("ROOT=" + str(raiz), flush=True)
        urls = executar_git(raiz, "remote", "get-url", "--all", "origin").splitlines()
        if not urls or not all(origem_mec(u) for u in urls):
            raise RuntimeError("Origin não corresponde ao projeto MEC-Servicos.")
        print("ORIGIN_MEC_CONFIRMADO=True", flush=True)
        exigir_backend_parado()
        relatorio["etapa"] = "conferir_base"
        plano = plano_arquivos(raiz)
        pacote = json.loads(seguro(raiz, "frontend/package.json").read_text(encoding="utf-8-sig"))
        if not pacote.get("scripts", {}).get("build"):
            raise RuntimeError("Comando build do frontend não encontrado.")
        npm = shutil.which("npm.cmd" if os.name == "nt" else "npm")
        if not npm:
            raise RuntimeError("npm não encontrado.")
        os.chdir(raiz)
        banco, acesso = configuracao_bancos(raiz)
        contas = conferir_d31(raiz, banco, acesso)
        negocio_antes = ler_historico(banco)
        acesso_antes = ler_historico(acesso)
        relatorio["contas_ativas_disponiveis"] = contas
        print("BASE_D31_E_OFICINA_OK=True", flush=True)
        relatorio["etapa"] = "backup"
        backup = seguro(raiz, "_mec_backups/D31_FIX2_MODO_TESTE_LOCAL_" + datetime.now().strftime("%Y%m%d_%H%M%S_%f"))
        # Este backup contém somente fontes e build; bancos são abertos em modo leitura.
        backup.mkdir(parents=True)
        relatorio["backup"] = str(backup)
        print("BACKUP_DIR=" + str(backup), flush=True)
        dist = seguro(raiz, "frontend/dist")
        dist_existia = dist.exists()
        if dist_existia:
            shutil.copytree(dist, backup / "frontend_dist")
        for nome in plano:
            alvo = raiz / nome
            originais[nome] = alvo.read_bytes() if alvo.exists() else None
            if originais[nome] is not None:
                copia = backup / "originais" / nome
                copia.parent.mkdir(parents=True, exist_ok=True)
                copia.write_bytes(originais[nome])
            for pasta in alvo.parents:
                if pasta == raiz:
                    break
                if not pasta.exists() and pasta not in pastas_novas:
                    pastas_novas.append(pasta)
        (backup / "MANIFESTO.json").write_text(json.dumps({n: None if b is None else sha(b) for n, b in originais.items()}, indent=2) + "\n", encoding="utf-8")
        relatorio["etapa"] = "aplicar_fontes"
        for nome, conteudo in plano.items():
            alterados.append(nome)
            gravar_atomico(raiz / nome, conteudo)
        print("ARQUIVOS_D31_FIX2_APLICADOS=" + str(len(plano)), flush=True)
        with tempfile.TemporaryDirectory(prefix="mec_d31_fix2_testes_") as pasta:
            ambiente = dict(os.environ)
            ambiente["MEC_URL_BANCO_DADOS"] = "sqlite:///" + (Path(pasta) / "negocio.db").resolve().as_posix()
            ambiente["MEC_ACESSOS_DB"] = str(Path(pasta) / "acesso.db")
            ambiente["MEC_MODO_TESTE_LOCAL"] = "0"
            ambiente["MEC_AMBIENTE"] = "teste"
            ambiente["MEC_COOKIE_SEGURO"] = "0"
            executar(raiz, "pytest", [sys.executable, "-m", "pytest", "tests", "-q", "--ignore=tests/mold"], ambiente, relatorio)
            build_iniciado = True
            executar(raiz / "frontend", "npm_build", [npm, "run", "build"], ambiente, relatorio)
        relatorio["etapa"] = "conferir_preservacao"
        if ler_historico(banco) != negocio_antes:
            raise RuntimeError("O banco de negócio mudou durante a instalação; nenhum registro será sobrescrito.")
        if ler_historico(acesso) != acesso_antes:
            raise RuntimeError("O banco de acesso mudou durante a instalação; nenhuma conta será sobrescrita.")
        relatorio.update({"resultado": "OK", "etapa": "concluido", "arquivos_alterados": alterados,
            "historico_negocio_preservado": True, "contas_e_senhas_preservadas": True,
            "comando_teste": r".\.venv\Scripts\python.exe .\MEC_SERVICOS_INICIAR_TESTE_LOCAL.py",
            "historico_negocio_sha256": negocio_antes, "historico_acesso_sha256": acesso_antes})
        concluido = True
        print("HISTORICO_NEGOCIO_PRESERVADO=True", flush=True)
        print("CONTAS_E_SENHAS_PRESERVADAS=True", flush=True)
        try:
            salvar_relatorio(raiz, relatorio)
        except OSError:
            print("RELATORIO_NAO_GRAVADO=True; preserve a saída do terminal.", flush=True)
        print("RESULTADO=OK", flush=True)
        print(r"Inicie: .\.venv\Scripts\python.exe .\MEC_SERVICOS_INICIAR_TESTE_LOCAL.py", flush=True)
        print("Mantenha o frontend com npm run dev. Atualize http://localhost:5173 e escolha Fornecedor / oficina mecanica / Empresa #1.", flush=True)
        print("Abra Produção para a OS #3. Use Trocar perfil para abrir a administração.", flush=True)
        return 0
    except (Exception, KeyboardInterrupt) as erro:
        relatorio["erro"] = str(erro) or "Operação interrompida."
        print("ETAPA=" + relatorio["etapa"], flush=True)
        print("ERRO=" + relatorio["erro"], flush=True)
        if raiz and alterados and not concluido:
            falhas = []
            for nome in reversed(alterados):
                try:
                    if originais[nome] is None:
                        (raiz / nome).unlink(missing_ok=True)
                    else:
                        gravar_atomico(raiz / nome, originais[nome])
                except OSError as falha:
                    falhas.append(str(falha))
            if build_iniciado:
                try:
                    if dist.exists():
                        shutil.rmtree(dist)
                    if dist_existia:
                        shutil.copytree(backup / "frontend_dist", dist)
                except OSError as falha:
                    falhas.append(str(falha))
            for p in sorted(pastas_novas, key=lambda p: len(p.parts), reverse=True):
                try:
                    if p.exists() and not any(p.iterdir()):
                        p.rmdir()
                except OSError as falha:
                    falhas.append(str(falha))
            relatorio["restaurado"] = not falhas
            if falhas:
                relatorio["falhas_restauracao"] = falhas
            print("RESTAURADO=" + str(relatorio["restaurado"]), flush=True)
        if raiz:
            try:
                salvar_relatorio(raiz, relatorio)
            except OSError:
                print("RELATORIO_NAO_GRAVADO=True", flush=True)
        print("RESULTADO=ERRO", flush=True)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
